                // Add objects for joined Serie rows

                $key3 = SeriePeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = SeriePeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = SeriePeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    SeriePeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (Subserie) to the collection in $obj3 (Serie)
                $obj3->addSubserie($obj1);

            } // if joined row is not null

                // Add objects for joined TipoFirmaDigital rows

                $key4 = TipoFirmaDigitalPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = TipoFirmaDigitalPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = TipoFirmaDigitalPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    TipoFirmaDigitalPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Subserie) to the collection in $obj4 (TipoFirmaDigital)
                $obj4->addSubserie($obj1);

            } // if joined row is not null

                // Add objects for joined NivelConfidencialidad rows

                $key5 = NivelConfidencialidadPeer::getPrimaryKeyHashFromRow($row, $startcol5);
                if ($key5 !== null) {
                    $obj5 = NivelConfidencialidadPeer::getInstanceFromPool($key5);
                    if (!$obj5) {
    
                        $cls = NivelConfidencialidadPeer::getOMClass();

                    $obj5 = new $cls();
                    $obj5->hydrate($row, $startcol5);
                    NivelConfidencialidadPeer::addInstanceToPool($obj5, $key5);
                } // if $obj5 already loaded

                // Add the $obj1 (Subserie) to the collection in $obj5 (NivelConfidencialidad)
                $obj5->addSubserie($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

    /**
